import{_ as h,I as e,o as p,c,b6 as l,j as a,J as s,w as n,a as i}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"تطوير منصة وكلاء ذكاء اصطناعي مشابهة لـ Dify - مشروع عملي","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/stage-2/assignments/custom-dify-agent-platform/index.md","filePath":"ar-sa/stage-2/assignments/custom-dify-agent-platform/index.md"}'),b={name:"ar-sa/stage-2/assignments/custom-dify-agent-platform/index.md"},u={style:{margin:"32px 0"}};function k(g,t,f,m,_,E){const r=e("StepBar"),d=e("ClientOnly"),o=e("el-card");return p(),c("div",null,[t[2]||(t[2]=l('<h1 id="تطوير-منصة-وكلاء-ذكاء-اصطناعي-مشابهة-لـ-dify-مشروع-عملي" tabindex="-1">تطوير منصة وكلاء ذكاء اصطناعي مشابهة لـ Dify - مشروع عملي <a class="header-anchor" href="#تطوير-منصة-وكلاء-ذكاء-اصطناعي-مشابهة-لـ-dify-مشروع-عملي" aria-label="Permalink to “تطوير منصة وكلاء ذكاء اصطناعي مشابهة لـ Dify - مشروع عملي”">​</a></h1><h2 id="نظرة-عامة" tabindex="-1">نظرة عامة <a class="header-anchor" href="#نظرة-عامة" aria-label="Permalink to “نظرة عامة”">​</a></h2><p>يتطلب منك هذا المشروع العملي العمل على أساس مستند متطلبات منتج (PRD) حقيقي، وبناء منصة وكلاء ذكاء اصطناعي تحاكي التجربة الأساسية لـ Dify من الصفر. ستبني وحدة تحكم المستخدم ولوحة الإدارة الخلفية ومنصة خلفية لتحقيق الوظائف الأساسية مثل إدارة الوكلاء الذكيين والمحادثات والسجلات وقواعد المعرفة.</p><p>هذا هو مشروع Stage 2 التطبيقي الشامل. على عكس المشاريع السابقة ذات الصفحة أو الوظيفة الواحدة، يتطلب منك هذا المشروع بناء منتج AI بـ &quot;طابع منصة&quot; - يتضمن أدواراً متعددة ووحدات متعددة واستمرارية البيانات وسلسلة استدعاء النماذج.</p><h2 id="المعارف-المسبقة" tabindex="-1">المعارف المسبقة <a class="header-anchor" href="#المعارف-المسبقة" aria-label="Permalink to “المعارف المسبقة”">​</a></h2><p>قبل البدء في هذا المشروع، يجب أن تكون قد أتقنت المحتوى التالي:</p><ul><li>تصميم واجهات الويب واستخدام مكتبات المكونات (<a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a>، <a href="./../../frontend/modern-component-library/">المكتبة الحديثة للمكونات</a>)</li><li>تصميم وتطوير واجهات البرمجيات الخلفية (<a href="./../../backend/ai-interface-code/">كتابة كود الواجهات</a>)</li><li>أساسيات قواعد البيانات و Supabase (<a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a>)</li><li>سير عمل Git والنشر (<a href="./../../backend/git-workflow/">Git و GitHub</a>، <a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a>)</li></ul><h2 id="أهداف-التعلم" tabindex="-1">أهداف التعلم <a class="header-anchor" href="#أهداف-التعلم" aria-label="Permalink to “أهداف التعلم”">​</a></h2><p>بعد إكمال هذا المشروع العملي، ستتمكن من:</p><ol><li>قراءة وفهم PRD حقيقي واستخراج قائمة مهام التطوير منه</li><li>تصميم هيكل الصفحات ونماذج البيانات لمنصة الوكلاء الذكيين</li><li>تنفيذ سلسلة كاملة من إنشاء الوكيل الذكي والمحادثات وتسجيل السجلات</li><li>استخدام AI للمساعدة في تطوير منتجات من نوع المنصات</li><li>إكمال الاختبار الشامل من طرف إلى طرف وتسليم نموذج أولي لمنصة AI قابل للعرض</li></ol><h2 id="مقدمة-المشروع" tabindex="-1">مقدمة المشروع <a class="header-anchor" href="#مقدمة-المشروع" aria-label="Permalink to “مقدمة المشروع”">​</a></h2><p>المنتج الذي ستبنيه هو منصة وكلاء ذكاء اصطناعي مشابهة لـ Dify، تتضمن نظامين فرعيين:</p><table tabindex="0"><thead><tr><th>النظام الفرعي</th><th>المسؤولية</th></tr></thead><tbody><tr><td><strong>وحدة تحكم المستخدم</strong></td><td>إنشاء وكلاء ذكيين، تكوين Prompt، بدء المحادثات، عرض السجلات، إدارة قواعد المعرفة</td></tr><tr><td><strong>لوحة الإدارة الخلفية</strong></td><td>عرض بيانات المستخدمين، استخدام موارد المنصة، إحصائيات الاستدعاءات</td></tr></tbody></table><p>يجب أن تدعم الواجهة الخلفية القدرات الأساسية التالية: إدارة الوكلاء الذكيين، إدارة الجلسات، تخزين الرسائل، استدعاء النماذج، تسجيل سجلات الاستدعاءات، الاتصال بقواعد المعرفة.</p><div class="tip custom-block"><p class="custom-block-title">مدخل PRD</p><p>مستند متطلبات هذا المشروع متاح على GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/custom-dify-agent-platform/PRD.md" target="_blank" rel="noreferrer">عرض PRD</a></p></div>',15)),a("div",u,[s(d,null,{default:n(()=>[s(r,{active:0,items:[{title:"تحليل المتطلبات",description:"قراءة PRD وتوضيح الصفحات وحدود القدرات والمصادقة ونماذج البيانات"},{title:"بناء الهيكل",description:"استخدام AI لإنشاء هيكل وحدة تحكم المستخدم ولوحة الإدارة"},{title:"التطوير التكراري",description:"إضافة الوكلاء والمحادثات والسجلات وقواعد المعرفة لكل وحدة"},{title:"الاختبار والنشر",description:"الاختبار الشامل من طرف إلى طرف والنشر والتحضير للعرض"}]})]),_:1})]),t[3]||(t[3]=l(`<h2 id="الجزء-الأول-تحليل-المتطلبات" tabindex="-1">الجزء الأول: تحليل المتطلبات <a class="header-anchor" href="#الجزء-الأول-تحليل-المتطلبات" aria-label="Permalink to “الجزء الأول: تحليل المتطلبات”">​</a></h2><h3 id="_1-1-قراءة-prd" tabindex="-1">1.1 قراءة PRD <a class="header-anchor" href="#_1-1-قراءة-prd" aria-label="Permalink to “1.1 قراءة PRD”">​</a></h3><p>افتح مستند PRD، وركز على الإجابة عن الأسئلة التالية:</p><ul><li>ما الذي يجب إدخاله في MVP من الوكلاء والجلسات والسجلات وقواعد المعرفة؟</li><li>هل تم تحديد قائمة الصفحات والمسارات؟</li><li>ما هي حدود استدعاء النماذج وتسجيل السجلات؟</li><li>هل يتم تأجيل التعددية والعمليات المعقدة؟</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>إذا لم تكن لديك إجابات واضحة على الأسئلة أعلاه، لا تبدأ في كتابة الكود. سوء فهم المتطلبات هو السبب الأكثر شيوعاً لإعادة العمل.</p></div><h3 id="_1-2-تأكيد-بنية-النظام" tabindex="-1">1.2 تأكيد بنية النظام <a class="header-anchor" href="#_1-2-تأكيد-بنية-النظام" aria-label="Permalink to “1.2 تأكيد بنية النظام”">​</a></h3><p>بناءً على PRD، رتب البنية الشاملة للنظام:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; app[&quot;وحدة تحكم المستخدم&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;لوحة الإدارة الخلفية&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;المصادقة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; agent[&quot;تكوين الوكيل الذكي&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; chat[&quot;جلسة المحادثة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; llm[&quot;استدعاء النموذج&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; db[&quot;قاعدة البيانات&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; kb[&quot;الاتصال بقاعدة المعرفة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; logs[&quot;سجلات الاستدعاءات ونظرة عامة على المنصة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  logs --&gt; db</span></span></code></pre></div><h2 id="الجزء-الثاني-بناء-هيكل-المشروع" tabindex="-1">الجزء الثاني: بناء هيكل المشروع <a class="header-anchor" href="#الجزء-الثاني-بناء-هيكل-المشروع" aria-label="Permalink to “الجزء الثاني: بناء هيكل المشروع”">​</a></h2><h3 id="_2-1-إنشاء-الصفحات-الأمامية" tabindex="-1">2.1 إنشاء الصفحات الأمامية <a class="header-anchor" href="#_2-1-إنشاء-الصفحات-الأمامية" aria-label="Permalink to “2.1 إنشاء الصفحات الأمامية”">​</a></h3><p>مرجع لموجه الأوامر:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>بناءً على PRD الحالي، ساعدني في إنشاء هيكل أمامي لمنصة وكلاء ذكاء اصطناعي مشابهة لـ Dify.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>1. جانب المستخدم يتضمن: تسجيل الدخول، قائمة الوكلاء، تكوين الوكيل، صفحة المحادثة، صفحة السجلات، صفحة قاعدة المعرفة</span></span>
<span class="line"><span>2. جانب الإدارة يتضمن: الصفحة الرئيسية للوحة التحكم، نظرة عامة على المستخدمين، نظرة عامة على استخدام الموارد</span></span>
<span class="line"><span>3. إنشاء هيكل الصفحات والبيانات الوهمية فقط، دون ربط واجهات حقيقية</span></span>
<span class="line"><span>4. النمط يجب أن يشبه منصات AI الحديثة</span></span></code></pre></div><h3 id="_2-2-التحقق-من-هيكل-الصفحات" tabindex="-1">2.2 التحقق من هيكل الصفحات <a class="header-anchor" href="#_2-2-التحقق-من-هيكل-الصفحات" aria-label="Permalink to “2.2 التحقق من هيكل الصفحات”">​</a></h3><p>تحقق من كل عنصر:</p><ul><li>[ ] هل مدخلات وحدة تحكم المستخدم ولوحة الإدارة الخلفية مفصولة</li><li>[ ] هل صفحات قائمة الوكلاء والتكوين والمحادثة والسجلات وقاعدة المعرفة كاملة</li><li>[ ] هل يمكن الوصول إلى الصفحة الرئيسية للوحة التحكم ونظرة عامة على المستخدمين</li><li>[ ] هل تعرض البيانات الوهمية حالات واجهة المستخدم الأساسية</li></ul><h2 id="الجزء-الثالث-التطوير-التكراري" tabindex="-1">الجزء الثالث: التطوير التكراري <a class="header-anchor" href="#الجزء-الثالث-التطوير-التكراري" aria-label="Permalink to “الجزء الثالث: التطوير التكراري”">​</a></h2><h3 id="_3-1-التقدم-حسب-الوحدات" tabindex="-1">3.1 التقدم حسب الوحدات <a class="header-anchor" href="#_3-1-التقدم-حسب-الوحدات" aria-label="Permalink to “3.1 التقدم حسب الوحدات”">​</a></h3><p>على أساس الهيكل، أضف الوظائف حسب الوحدات بالترتيب التالي:</p><ol><li><strong>المصادقة</strong>: التسجيل، تسجيل الدخول، التمييز بين الأدوار</li><li><strong>إدارة الوكلاء الذكيين</strong>: الإنشاء، التعديل، الحذف، تكوين Prompt</li><li><strong>وظيفة المحادثة</strong>: إنشاء الجلسات، إرسال واستقبال الرسائل، استدعاء النماذج</li><li><strong>تسجيل السجلات</strong>: الوقت المستغرق، استخدام token، تسجيل الأخطاء</li><li><strong>الاتصال بقاعدة المعرفة</strong> (نقاط إضافية): رفع المستندات، البحث، حقن النتائج</li><li><strong>لوحة الإدارة الخلفية</strong>: بيانات المستخدمين، استخدام الموارد، إحصائيات الاستدعاءات</li></ol><p>بعد إكمال كل وحدة، استخدم الجدول التالي للفحص الذاتي:</p><table tabindex="0"><thead><tr><th>عنصر الفحص</th><th>طريقة التحقق</th></tr></thead><tbody><tr><td>توافق الصفحات</td><td>هل عدد الصفحات والوظائف يتوافق مع PRD</td></tr><tr><td>اكتمال الواجهات</td><td>هل واجهات agents و chat و logs و knowledge كاملة</td></tr><tr><td>عزل الصلاحيات</td><td>هل يمكن للمستخدمين إدارة وكلائهم وجلساتهم فقط</td></tr><tr><td>توافق البيانات</td><td>هل بيانات messages و logs و documents متطابقة</td></tr><tr><td>قابلية العرض</td><td>هل يمكن عرض سلسلة &quot;إنشاء وكيل ← محادثة ← عرض السجلات&quot; الكاملة</td></tr></tbody></table><h3 id="_3-2-الاتصال-بقاعدة-المعرفة-نقاط-إضافية" tabindex="-1">3.2 الاتصال بقاعدة المعرفة (نقاط إضافية) <a class="header-anchor" href="#_3-2-الاتصال-بقاعدة-المعرفة-نقاط-إضافية" aria-label="Permalink to “3.2 الاتصال بقاعدة المعرفة (نقاط إضافية)”">​</a></h3><p>إذا كنت ترغب في إضافة قدرات قاعدة المعرفة، يمكنك إضافة &quot;مفتاح قاعدة المعرفة&quot; لكل وكيل ذكي:</p><ul><li>عند التفعيل، ابحث أولاً عن أجزاء المعرفة، ثم أرسلها مع سؤال المستخدم إلى النموذج</li><li>عند التعطيل، استجب وفق وضع المحادثة العادية</li></ul><p>لا حاجة للسعي لتحقيق RAG معقد في الإصدار الأول، فقط تأكد من أن &quot;نتائج البحث مرئية وسلسلة الاستدعاء قابلة للتفسير&quot;.</p><h2 id="الجزء-الرابع-الاختبار-والنشر" tabindex="-1">الجزء الرابع: الاختبار والنشر <a class="header-anchor" href="#الجزء-الرابع-الاختبار-والنشر" aria-label="Permalink to “الجزء الرابع: الاختبار والنشر”">​</a></h2><h3 id="_4-1-اختبار-من-طرف-إلى-طرف" tabindex="-1">4.1 اختبار من طرف إلى طرف <a class="header-anchor" href="#_4-1-اختبار-من-طرف-إلى-طرف" aria-label="Permalink to “4.1 اختبار من طرف إلى طرف”">​</a></h3><p>تحقق من السيناريوهات التالية على الأقل:</p><ul><li>تسجيل حساب ← إنشاء وكيل ذكي ← تكوين Prompt ← بدء محادثة ← عرض السجلات</li><li>تسجيل دخول المسؤول ← عرض بيانات المستخدمين ← عرض إحصائيات الاستدعاءات</li></ul><p>تحقق قبل النشر:</p><ul><li>[ ] جميع الواجهات الأساسية لديها تحقق من تسجيل الدخول</li><li>[ ] التحقق من ملكية الوكيل الذكي يعمل بشكل صحيح</li><li>[ ] سجلات الجلسات والسجلات محفوظة فعلياً في قاعدة البيانات</li><li>[ ] مفتاح النموذج يستخدم متغيرات البيئة وليس مشفراً بشكل ثابت</li><li>[ ] رسائل الخطأ مرئية في الواجهة الأمامية وليست فقط في وحدة التحكم</li></ul><h3 id="_4-2-النشر" tabindex="-1">4.2 النشر <a class="header-anchor" href="#_4-2-النشر" aria-label="Permalink to “4.2 النشر”">​</a></h3><p>انشر المشروع في بيئة الإنترنت العامة. مرجع لدروس النشر: <a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a>، <a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a>.</p><h2 id="المخرجات-المطلوبة" tabindex="-1">المخرجات المطلوبة <a class="header-anchor" href="#المخرجات-المطلوبة" aria-label="Permalink to “المخرجات المطلوبة”">​</a></h2><p>بعد إكمال هذا المشروع، يجب عليك تقديم المحتوى التالي:</p><ul><li>[ ] رابط عرض عبر الإنترنت قابل للوصول</li><li>[ ] رابط مستودع الكود المصدري (يتضمن README)</li><li>[ ] مستند PRD</li><li>[ ] لقطات شاشة للصفحات الرئيسية (صفحة إدارة الوكلاء، صفحة المحادثة، صفحة السجلات، الصفحة الرئيسية للوحة التحكم)</li><li>[ ] فيديو عرض مدته 60 ثانية (يغطي إنشاء وكيل ← محادثة ← عرض السجلات)</li></ul><p>يجب أن يتضمن README على الأقل: مقدمة المشروع، شرح البنية، التقنيات المستخدمة، خطوات التشغيل المحلي، قائمة متغيرات البيئة، شرح الواجهات.</p><h2 id="معايير-التقييم" tabindex="-1">معايير التقييم <a class="header-anchor" href="#معايير-التقييم" aria-label="Permalink to “معايير التقييم”">​</a></h2><table tabindex="0"><thead><tr><th>البُعد</th><th>المتطلبات الأساسية</th><th>المتطلبات المتقدمة</th></tr></thead><tbody><tr><td>اكتمال المنصة</td><td>صفحات agents / chat / logs تعمل</td><td>توجد تنقل واضح ولغة تصميم موحدة</td></tr><tr><td>حلقة الأعمال</td><td>يمكن إنشاء وكيل ذكي وإجراء محادثة حقيقية</td><td>دعم التبديل بين وكلاء متعددين وجلسات سابقة</td></tr><tr><td>البيانات والتتبع</td><td>الرسائل وسجلات الاستدعاءات قابلة للاستعلام</td><td>توجد لوحة إحصائيات لـ token / الوقت المستغرق</td></tr><tr><td>أمان الصلاحيات</td><td>فقط المستخدمون المسجلون يمكنهم الوصول للواجهات الأساسية</td><td>التحقق من ملكية الموارد مكتمل</td></tr><tr><td>التسليم الهندسي</td><td>قابل للنشر والعرض و README واضح</td><td>الاتصال بقاعدة المعرفة ونتائج البحث قابلة للتفسير</td></tr></tbody></table><h2 id="التحقق-قبل-التقديم" tabindex="-1">التحقق قبل التقديم <a class="header-anchor" href="#التحقق-قبل-التقديم" aria-label="Permalink to “التحقق قبل التقديم”">​</a></h2>`,40)),s(o,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:n(()=>[...t[0]||(t[0]=[a("div",{style:{"font-weight":"bold","font-size":"16px"}},"نظرة أخيرة قبل التقديم",-1)])]),default:n(()=>[t[1]||(t[1]=a("ul",{style:{"list-style-type":"none","padding-left":"0"}},[a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" بعد تسجيل الدخول يمكن الوصول لصفحات إدارة الوكلاء والمحادثة والسجلات")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" يمكن إنشاء وكيل واحد على الأقل وإجراء محادثة ناجحة")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" كل جولة سؤال وجواب يمكن العثور على سجلها في قاعدة البيانات")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" عند فشل الاستدعاء تكون رسالة الخطأ مرئية في الواجهة الأمامية والسجل مسجل")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" المشروع منشور و README وفيديو العرض مكتملان")])])],-1))]),_:1}),t[4]||(t[4]=l('<h2 id="المراجع" tabindex="-1">المراجع <a class="header-anchor" href="#المراجع" aria-label="Permalink to “المراجع”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a></li><li><a href="./../../frontend/modern-component-library/">تحديث واجهتك باستخدام المكتبة الحديثة للمكونات</a></li><li><a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a></li><li><a href="./../../backend/ai-interface-code/">كتابة كود الواجهات بمساعدة النماذج اللغوية الكبيرة</a></li><li><a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a></li></ul>',2))])}const x=h(b,[["render",k]]);export{P as __pageData,x as default};
